-- Starter schema. Review and configure RLS policies before production.
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text not null default 'reader', created_at timestamptz not null default now());
create table if not exists public.ipo_master (id bigint generated by default as identity primary key, company_name text not null, issue_type text, open_date date, close_date date, listing_date date, price_band text, issue_size text, status text default 'upcoming', created_at timestamptz not null default now());
create table if not exists public.ipo_gmp (id bigint generated by default as identity primary key, ipo_id bigint references public.ipo_master(id) on delete cascade, gmp_value text, source text, observed_at timestamptz not null default now());
create table if not exists public.market_news (id bigint generated by default as identity primary key, title text not null, summary text, source text, source_url text, language text default 'en', status text not null default 'pending', published_at timestamptz, created_at timestamptz not null default now());
create table if not exists public.stock_data (id bigint generated by default as identity primary key, symbol text not null, company_name text, price numeric, change_percent numeric, source text, observed_at timestamptz not null default now());
create table if not exists public.market_indices (id bigint generated by default as identity primary key, index_name text not null, value numeric, change_percent numeric, source text, observed_at timestamptz not null default now());
create table if not exists public.automation_logs (id bigint generated by default as identity primary key, task_name text not null, status text, details text, created_at timestamptz not null default now());
